using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class MyTools
{
    [McpServerTool, Description("Adds two numbers together.")]
    public static double Add(double a, double b) => a + b;

    [McpServerTool, Description("Gets the current server time in UTC.")]
    public static string GetServerTime() =>
        DateTime.UtcNow.ToString("o");
}

using ModelContextProtocol.Server;
using System.Text.Json;

[McpServerResourceType]
public static class MyResources
{
    // Direct resource — listed via resources/list, read by exact URI.
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "AppSettings",
        Title = "Application Settings",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var settings = new
        {
            maxRetries = 3,
            timeoutSeconds = 30,
            featureFlags = new
            {
                darkMode = true,
                betaFeatures = false,
            },
            version = "1.0.0",
        };

        return JsonSerializer.Serialize(settings, new JsonSerializerOptions { WriteIndented = true });
    }

    // Resource template — listed via resources/templates/list.
    // The {name} segment is bound to the method parameter.
    [McpServerResource(
        UriTemplate = "config://app/settings/{name}",
        Name = "AppSettingByName",
        Title = "Single Application Setting",
        MimeType = "application/json")]
    public static string GetSettingByName(string name)
    {
        var settings = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
        {
            ["maxRetries"] = 3,
            ["timeoutSeconds"] = 30,
            ["version"] = "1.0.0",
        };

        if (settings.TryGetValue(name, out var value))
        {
            return JsonSerializer.Serialize(new { name, value });
        }

        return JsonSerializer.Serialize(new { name, error = "Setting not found" });
    }
}

